    std::cout << lote.cantidad() << '[';
    for (int i = 0; i < lote.cantidad(); ++i) {
        int valor = -1;
        lote.leer(i, valor);
        if (i != 0) {
            std::cout << ',';
        }
        std::cout << valor;
    }
    std::cout << ']';
}

